const groups=[
["Proses 1. Konteks Organisasi",[
["Apakah perusahaan melakukan identifikasi isu internal dan isu eksternal yang berpengaruh terhadap kinerja HSE?",10],
["Apakah perusahaan melakukan identifikasi kebutuhan dan harapan pihak berkepentingan yang berpengaruh terhadap kinerja HSE?",10],
["Apakah perusahaan menetapkan dan menerapkan sistem manajemen HSE yang terintegrasi dengan bisnis proses perusahaan?",15]]],
["Proses 2. Kepemimpinan",[
["Apakah manajemen puncak terlibat aktif dalam pengelolaan aspek HSE, termasuk rencana kerja, budaya HSE dan inspeksi manajemen?",10],
["Apakah perusahaan mempunyai kebijakan HSE tertulis dan dikomunikasikan kepada seluruh pekerja?",10],
["Apakah perusahaan memiliki struktur HSE yang memadai dan diisi personel kompeten?",10],
["Apakah tugas dan tanggung jawab HSE tercantum dalam uraian tugas seluruh level pekerja?",5],
["Apakah Komite HSE (P2K3) telah dibentuk di perusahaan?",10]]],
["Proses 3. Perencanaan",[
["Apakah perusahaan memiliki sistem pengelolaan risiko HSE terkait aktivitas operasional?",10],
["Apakah daftar risiko HSE didokumentasikan dan dikomunikasikan kepada pekerja terkait?",5],
["Apakah mitigasi/tindakan dalam daftar risiko telah dilaksanakan dan dipastikan pemenuhannya?",5],
["Apakah perusahaan mengidentifikasi dan mengevaluasi kewajiban kepatuhan terkait HSE?",10],
["Apakah perusahaan memiliki dokumen/persetujuan lingkungan sesuai lingkup kegiatan (AMDAL/DELH, UKL-UPL/DPLH, SPPLH)?",15],
["Apakah perusahaan memiliki sasaran kinerja HSE?",10],
["Apakah perusahaan memiliki rencana kerja HSE yang mengacu pada target kinerja HSE?",10]]],
["Proses 4. Pendukung",[
["Apakah perusahaan memiliki sistem pelatihan HSE untuk seluruh level organisasi?",15],
["Apakah perusahaan menyusun program training HSE dan memastikan efektivitas pelaksanaannya?",15],
["Apakah perusahaan mempunyai program pelatihan HSE bagi pekerja baru?",10],
["Apakah perusahaan memiliki program rapat aspek HSE dari tingkat manajemen hingga pekerja/fungsi?",10],
["Apakah perusahaan memiliki dan melaksanakan program asuransi ketenagakerjaan?",10],
["Apakah perusahaan memiliki dan melaksanakan sistem Fit To Work, terutama untuk pekerjaan berisiko tinggi?",15],
["Apakah perusahaan memiliki personel terlatih untuk Pertolongan Pertama Pada Kecelakaan (P3K)?",15],
["Apakah perusahaan memiliki sistem untuk mengkomunikasikan aspek HSE?",10],
["Apakah perusahaan mengkomunikasikan standar industri dan peraturan HSE terbaru yang berlaku?",10],
["Apakah perusahaan memiliki sistem pengendalian dokumen dan rekaman HSE?",10]]],
["Proses 5. Pengendalian Operasional",[
["Apakah perusahaan memiliki prosedur kerja aspek HSE berdasarkan standar, peraturan dan praktik terbaik?",10],
["Apakah perusahaan menyediakan APD yang layak dan memastikan penggunaannya sesuai fungsi?",5],
["Apakah perusahaan mengelola limbah rumah tangga, limbah B3 dan air limbah sesuai ketentuan?",10],
["Apakah perusahaan memiliki sistem Management of Change untuk perubahan personel, peralatan, proses dan dokumentasi?",10],
["Apakah perusahaan memiliki sistem pengelolaan subkontraktor yang mensyaratkan pemenuhan HSE selama kontrak?",10],
["Apakah perusahaan memiliki sistem pemeliharaan peralatan untuk memastikan kesiapan dan kelayakan fungsi?",15],
["Apakah perusahaan memiliki dan menerapkan sistem izin kerja untuk mengendalikan bahaya?",10],
["Apakah perusahaan menggunakan peralatan hemat energi?",15],
["Apakah peralatan pencegahan/penanggulangan kebakaran, ledakan dan pencemaran terpelihara serta berfungsi?",15],
["Apakah perusahaan memiliki sistem pengelolaan keadaan darurat dan rencana darurat sesuai kegiatan operasional?",15]]],
["Proses 6. Evaluasi Kinerja",[
["Apakah perusahaan melakukan pengukuran dan pemantauan lingkungan kerja?",15],
["Apakah perusahaan melakukan pengelolaan dan pemantauan sesuai dokumen lingkungan?",15],
["Apakah perusahaan memiliki sistem audit HSE yang dilaksanakan personel kompeten?",20],
["Apakah perusahaan melakukan inspeksi terhadap peralatan yang digunakan?",15],
["Apakah perusahaan memiliki program observasi dan intervensi aspek HSE (pengamatan keselamatan kerja)?",10],
["Apakah perusahaan memiliki sistem pemantauan kinerja HSE secara periodik?",15],
["Apakah perusahaan memiliki sistem tinjauan manajemen?",15],
["Apakah tinjauan manajemen dilaksanakan periodik dan hasilnya ditindaklanjuti?",5]]],
["Proses 7. Perbaikan",[
["Apakah perusahaan memiliki sistem pelaporan dan investigasi kecelakaan termasuk insiden berpotensi Major Accident?",10],
["Apakah temuan audit, inspeksi dan rekomendasi investigasi kecelakaan telah ditindaklanjuti?",20],
["Apakah kasus insiden dikomunikasikan sebagai pembelajaran agar tidak terulang?",10]]],
["Proses 8. ESG, Penghargaan dan Sanksi",[
["Apakah perusahaan menerima penghargaan HSE dari badan/instansi terkait implementasi HSE?",10],
["Apakah perusahaan menerima sanksi/teguran/kewajiban perbaikan dari Pemerintah akibat pelanggaran HSE dalam tiga tahun terakhir?",10],
["Apakah perusahaan menerapkan ESG dalam praktik bisnisnya?",15]]]
];
const questions=groups.flatMap((g,gi)=>g[1].map((q,qi)=>({id:`${gi+1}.${String.fromCharCode(97+qi)}`,group:g[0],text:q[0],max:q[1]})));
let db={vendors:[]}, accounts=[], session=null, authMode='login';
function showAuth(mode){authMode=mode;document.getElementById('authTitle').textContent=mode==='login'?'Masuk ke aplikasi':'Pendaftaran akun';document.getElementById('authDesc').textContent=mode==='login'?'Gunakan akun sesuai peran Anda.':'Pendaftaran mandiri hanya tersedia untuk Vendor.';document.getElementById('registerFields').classList.toggle('hide',mode!=='register');document.getElementById('tabLogin').classList.toggle('selected',mode==='login');document.getElementById('tabRegister').classList.toggle('selected',mode==='register');document.getElementById('authSubmit').textContent=mode==='login'?'Masuk':'Daftar Akun';document.getElementById('authError').textContent=''}
function rolesOf(r){return Array.isArray(r)?r:[r].filter(Boolean)}
function normalizeRoles(r){let rs=rolesOf(r);if(rs.includes('admin'))return ['admin'];if(rs.includes('vendor'))return ['vendor'];return [...new Set(rs)]}
function roleLabel(r){let labels={vendor:'Vendor',verifikator:'Verifikator',validator:'Validator',pengadaan:'Bagian Pengadaan',admin:'Admin'};return rolesOf(r).map(x=>labels[x]||x).join(' + ')}
function canAccess(p){let rs=rolesOf(session?.role);if(rs.includes('admin'))return true;let allowed={vendor:['dashboard','vendors','register','questionnaire'],verifikator:['dashboard','vendors','verification'],validator:['dashboard','vendors','validation','risk'],pengadaan:['dashboard','vendors','risk'],admin:['dashboard','vendors','register','questionnaire','verification','validation','risk','accounts']};return rs.some(r=>(allowed[r]||[]).includes(p))}
function defaultPage(){let rs=rolesOf(session?.role);return rs.includes('admin')?'dashboard':rs.includes('verifikator')?'verification':rs.includes('validator')?'validation':rs.includes('pengadaan')?'risk':'dashboard'}
function applyRoleAccess(){document.querySelectorAll('#nav button').forEach(b=>{b.style.display=canAccess(b.dataset.page)?'block':'none'});let b=document.querySelector('#nav button[data-page="'+page+'"]');if(b&&b.style.display==='none')go(defaultPage())}
function loginReady(){if(!session){document.getElementById('authScreen').style.display='flex';return}session.role=rolesOf(session.role);document.getElementById('authScreen').style.display='none';document.getElementById('whoami').textContent=(session.name||session.username)+' · '+roleLabel(session.role);applyRoleAccess()}
let currentId=null, page='dashboard';
function esc(s=''){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function vendor(){return db.vendors.find(v=>v.id===currentId)}
function newVendor(){return {id:'RCH-'+new Date().getFullYear()+'-'+String(Date.now()).slice(-5),name:'',nib:'',npwp:'',address:'',pic:'',email:'',phone:'',business:'',ossRisk:'',scope:'',branch:'',status:'Draft Pendaftaran',answers:{},docs:{},review:{},validation:{},created:new Date().toISOString().slice(0,10),docDate:'',fieldDate:''}}
function statusTag(s){let c=/Lulus|Valid|Selesai|Terbit/.test(s)?'green':/Tidak|Ditolak|Tidak Lulus/.test(s)?'red':/Perbaikan|Menunggu|Verifikasi|Validasi/.test(s)?'orange':'';return `<span class="tag ${c}">${esc(s)}</span>`}
function averageMatrix(v,stage,qid){
  const key=stage==='review'?'reviewByUser':'validationByUser';
  const records=Object.values(v?.[key]||{}).map(r=>r?.scores?.[qid]).filter(x=>x&&Number.isFinite(Number(x.score)));
  if(records.length) return records.reduce((a,x)=>a+Number(x.score),0)/records.length;
  const raw=(v?.[stage]||{})[qid]; const n=Number(raw&&typeof raw==='object'?raw.score:raw);
  return Number.isFinite(n)?n:0;
}
function score(v,stage){return questions.reduce((sum,q)=>sum+averageMatrix(v,stage,q.id)*q.max,0)}
function reviewerSummary(v,key){
  const records=Object.entries(v?.[key]||{});
  if(!records.length) return '<div class="empty small">Belum ada penilaian yang disimpan.</div>';
  const stageName=key==='reviewByUser'?'Verifikator':'Validator';
  return `<div class="tablewrap"><table><thead><tr><th>${stageName}</th><th>Waktu simpan</th><th>Jumlah kriteria</th><th>Nilai total</th></tr></thead><tbody>${records.map(([username,r])=>{const vals=Object.values(r.scores||{}).filter(x=>x&&Number.isFinite(Number(x.score)));const total=questions.reduce((a,q)=>a+Number(r.scores?.[q.id]?.score||0)*q.max,0);return `<tr><td><b>${esc(r.name||username)}</b><br><small>${esc(username)}</small></td><td>${r.date?new Date(r.date).toLocaleString('id-ID'):'-'}</td><td>${vals.length} / ${questions.length}</td><td>${total.toFixed(2)} / 565 (${(total/565*100).toFixed(2)}%)</td></tr>`}).join('')}</tbody></table></div>`;
}
function reviewerCriterionDetails(v,qid,key){const records=Object.entries(v?.[key]||{}).filter(([u,r])=>r?.scores?.[qid]&&Number.isFinite(Number(r.scores[qid].score)));if(!records.length)return 'Belum dinilai';return records.map(([u,r])=>`${esc(r.name||u)}: ${Number(r.scores[qid].score)}${r.scores[qid].comment?` — ${esc(r.scores[qid].comment)}`:''}`).join('<br>')}

function risk(n){if(n>=70)return 'Risiko Tinggi';if(n>=50)return 'Risiko Menengah';if(n>=35)return 'Risiko Rendah';return 'Tidak Lulus'}
function badgeRisk(n){let r=risk(n);return `<span class="tag ${n<35?'red':n>=70?'orange':'green'}">${r}</span>`}
function go(p){if(!session){document.getElementById('authScreen').style.display='flex';return}if(!canAccess(p)){alert('Akses tidak tersedia untuk peran '+roleLabel(session.role));return}page=p;document.querySelectorAll('#nav button').forEach(b=>b.classList.toggle('active',b.dataset.page===p));render()}
document.querySelectorAll('#nav button').forEach(b=>b.onclick=()=>go(b.dataset.page));
function render(){document.getElementById('topTitle').textContent=({dashboard:'Dashboard',vendors:'Data Penyedia',register:'Pendaftaran Vendor',questionnaire:'Pengisian Pra-Kualifikasi',verification:'Verifikasi Dokumen',validation:'Validasi Lapangan',risk:'Hasil & Lingkup Risiko',accounts:'Kelola Akun Internal'})[page];let el=document.getElementById('view');({dashboard:dash,vendors:vendorsPage,register:registerPage,questionnaire:questionnairePage,verification:verificationPage,validation:validationPage,risk:riskPage,accounts:accountsPage}[page]) (el)}
function dash(el){let vs=db.vendors, statuses=['Draft Pendaftaran','Menunggu Pengisian','Menunggu Verifikasi Dokumen','Perlu Perbaikan','Menunggu Validasi Lapangan','Tervalidasi','Tidak Lulus'];el.innerHTML=`<div class="heading"><div><div class="eyebrow">Portal manajemen kontraktor</div><h1>Dashboard RCHSEMS</h1><p>Pantau pendaftaran, pra-kualifikasi, verifikasi, validasi, dan klasifikasi risiko vendor.</p></div><button onclick="currentId=null;go('register')">＋ Daftarkan Vendor</button></div>
<div class="cards"><div class="card"><div class="muted">Total Penyedia</div><div class="metric">${vs.length}</div><small class="muted">Terdaftar dalam portal</small></div><div class="card"><div class="muted">Menunggu Verifikasi</div><div class="metric">${vs.filter(v=>v.status==='Menunggu Verifikasi Dokumen').length}</div><small class="muted">Tugas Unit Keselamatan</small></div><div class="card"><div class="muted">Menunggu Validasi</div><div class="metric">${vs.filter(v=>v.status==='Menunggu Validasi Lapangan').length}</div><small class="muted">Tinjauan lapangan</small></div><div class="card"><div class="muted">Tervalidasi</div><div class="metric">${vs.filter(v=>v.status==='Tervalidasi').length}</div><small class="muted">Nilai lapangan final</small></div></div>
<div class="panel"><div class="row between"><h2>Alur proses</h2><span class="tag">Sesuai prosedur RCHSEMS</span></div><div class="cards" style="grid-template-columns:repeat(3,minmax(0,1fr))"><div><b>01 · Pendaftaran</b><p class="muted small">Data perusahaan, NIB/OSS, lingkup kerja.</p></div><div><b>02 · Pra-kualifikasi</b><p class="muted small">Isi 8 proses dan unggah bukti dokumen.</p></div><div><b>03 · Verifikasi</b><p class="muted small">Unit Keselamatan menilai dokumen.</p></div><div><b>04 · Validasi</b><p class="muted small">Validasi lapangan dan pembaruan nilai.</p></div><div><b>05 · Penetapan</b><p class="muted small">Klasifikasi risiko berdasarkan nilai lapangan.</p></div><div><b>06 · Sertifikat</b><p class="muted small">Vendor Management menerbitkan sertifikat.</p></div></div></div>
<div class="panel"><div class="row between"><h2>Aktivitas terbaru</h2><button class="secondary" onclick="go('vendors')">Lihat semua</button></div>${vs.length?vendorTable(vs.slice(-5).reverse()):'<div class="empty">Belum ada data vendor. Mulai dari pendaftaran vendor.</div>'}</div>
<div class="note small"><b>Catatan:</b> Data dan bukti tersimpan terpusat di server. Setiap pengguna hanya dapat menjalankan tindakan sesuai kewenangannya.</div>`}
function roleTargetPage(){let rs=rolesOf(session?.role);if(rs.includes('admin')||rs.includes('vendor'))return 'questionnaire';return defaultPage()}
function vendorTable(vs){return `<div class="tablewrap"><table><thead><tr><th>ID / Perusahaan</th><th>Lingkup</th><th>Status</th><th>Nilai PK</th><th>Kategori</th><th>Aksi</th></tr></thead><tbody>${vs.map(v=>`<tr><td><b>${esc(v.name||'(Nama belum diisi)')}</b><br><small class="muted">${esc(v.id)}</small></td><td>${esc(v.scope||'-')}</td><td>${statusTag(v.status)}</td><td>${((v.status==='Tervalidasi'?score(v,'validation'):score(v,'review'))/565*100).toFixed(2)}</td><td>${v.status==='Tervalidasi'?badgeRisk(score(v,'validation')/565*100):'-'}</td><td><button class="secondary" onclick="openVendor('${v.id}',roleTargetPage())">Buka</button></td></tr>`).join('')}</tbody></table></div>`}
function vendorsPage(el){el.innerHTML=`<div class="heading"><div><div class="eyebrow">Database vendor</div><h1>Data Penyedia</h1><p>Daftar dan status setiap perusahaan/lingkup yang didaftarkan.</p></div><button onclick="currentId=null;go('register')">＋ Vendor Baru</button></div><div class="panel">${db.vendors.length?vendorTable([...db.vendors].reverse()):'<div class="empty">Belum ada vendor.</div>'}</div>`}
function registerPage(el){let v=vendor()||newVendor();el.innerHTML=`<div class="heading"><div><div class="eyebrow">Langkah 1 dari 5</div><h1>Pendaftaran Vendor</h1><p>Isi data perusahaan dan lingkup yang akan dikualifikasi.</p></div></div><div class="stepbar"><span class="step on">1 Pendaftaran</span><span class="step">2 Pra-Kualifikasi</span><span class="step">3 Verifikasi</span><span class="step">4 Validasi</span><span class="step">5 Penetapan</span></div><form id="regForm" class="panel"><div class="formgrid">${field('Nama Perusahaan','name',v.name,true)}${field('NIB','nib',v.nib,true)}${field('NPWP','npwp',v.npwp)}${field('Tingkat Risiko OSS','ossRisk',v.ossRisk,false,'select',['Rendah','Menengah Rendah','Menengah Tinggi','Tinggi'])}${field('Alamat Perusahaan','address',v.address,true)}${field('Cabang/Unit yang didaftarkan','branch',v.branch)}${field('Penanggung Jawab HSE','pic',v.pic,true)}${field('Email Resmi','email',v.email,true,'email')}${field('Nomor Telepon','phone',v.phone)}${field('Bidang Usaha','business',v.business,true)}${field('Lingkup pekerjaan yang dimohonkan','scope',v.scope,true)}<div class="field wide"><label>Catatan / informasi tambahan</label><textarea name="notes">${esc(v.notes||'')}</textarea></div></div><div class="row between" style="margin-top:18px"><span class="muted small">Kolom bertanda * wajib diisi.</span><button type="submit">Simpan & Lanjut Pra-Kualifikasi →</button></div></form>`;document.getElementById('regForm').onsubmit=saveProfile;}

function field(label,name,value,req=false,type='text',opts=[]){let input=type==='select'?`<select name="${name}" ${req?'required':''}><option value="">Pilih...</option>${opts.map(o=>`<option ${value===o?'selected':''}>${o}</option>`).join('')}</select>`:`<input name="${name}" type="${type}" value="${esc(value||'')}" ${req?'required':''} ${type==='email'?'':''}>`;return `<div class="field"><label>${label}${req?' *':''}</label>${input}</div>`}
function openVendor(id,p){currentId=id;go(p)}
function questionnairePage(el){let v=vendor();if(!v){el.innerHTML=`<div class="empty panel">Pilih vendor terlebih dahulu dari <button onclick="go('vendors')">Data Penyedia</button> atau daftarkan vendor baru.</div>`;return}el.innerHTML=`<div class="heading"><div><div class="eyebrow">Langkah 2 dari 5 · ${esc(v.id)}</div><h1>Pra-Kualifikasi</h1><p>${esc(v.name)} · Isi ketersediaan dokumen dan unggah bukti untuk tiap proses.</p></div><button class="secondary" onclick="go('vendors')">Kembali ke daftar</button></div><div class="panel"><div class="row between"><div><b>Kelengkapan jawaban</b><p class="muted small">${Object.keys(v.answers).length} dari ${questions.length} pertanyaan terisi</p></div><b>${Math.round(Object.keys(v.answers).length/questions.length*100)}%</b></div><div class="progress"><div style="width:${Object.keys(v.answers).length/questions.length*100}%"></div></div></div><form id="qForm">${groups.map((g,gi)=>`<div class="panel" style="margin-top:14px"><h2>${esc(g[0])}</h2>${questions.filter(q=>q.group===g[0]).map(q=>`<div class="question"><div class="qmeta">Pertanyaan ${q.id} · Bobot maksimum ${q.max}</div><div class="qtitle">${esc(q.text)}</div><div class="choices"><label><input type="radio" name="a_${q.id}" value="Ya" ${v.answers[q.id]?.answer==='Ya'?'checked':''}> Ya, tersedia</label><label><input type="radio" name="a_${q.id}" value="Tidak" ${v.answers[q.id]?.answer==='Tidak'?'checked':''}> Tidak tersedia</label></div><div class="field" style="margin-top:10px"><label>Dokumen bukti (PDF, Word, Excel, JPG/PNG)</label><input type="file" multiple accept=".pdf,.doc,.docx,.xls,.xlsx,.jpg,.jpeg,.png,application/pdf,application/msword,application/vnd.openxmlformats-officedocument.wordprocessingml.document,application/vnd.ms-excel,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet,image/jpeg,image/png" data-doc="${q.id}"><small class="muted">${(v.answers[q.id]?.files?.length ? v.answers[q.id].files.map(f=>esc(f.name)).join('; ') : esc(v.answers[q.id]?.fileName||'Belum ada lampiran'))}. Format yang didukung: PDF, Word (.doc/.docx), Excel (.xls/.xlsx), JPG, dan PNG. File disimpan secara privat di server (maks. 15 MB per file).</small></div><div class="field" style="margin-top:8px"><label>Keterangan</label><input name="note_${q.id}" value="${esc(v.answers[q.id]?.note||'')}" placeholder="Nomor dokumen, masa berlaku, atau catatan"></div></div>`).join('')}</div>`).join('')}<div class="panel row between" style="margin-top:14px"><span class="muted small">Pastikan seluruh jawaban dan bukti relevan sebelum mengirim.</span><button type="submit">Simpan & Kirim untuk Verifikasi →</button></div></form>`;document.getElementById('qForm').onsubmit=submitQuestionnaire;document.querySelectorAll('[data-doc]').forEach(inp=>inp.onchange=()=>uploadEvidence(inp));}

function selectVendorOptions(){return db.vendors.map(v=>`<option value="${v.id}" ${currentId===v.id?'selected':''}>${esc(v.name||v.id)} — ${esc(v.id)}</option>`).join('')}
function picker(){return `<div class="field" style="max-width:560px;margin-bottom:16px"><label>Pilih vendor</label><select onchange="currentId=this.value;render()"><option value="">Pilih vendor...</option>${selectVendorOptions()}</select></div>`}
function verificationPage(el){let v=vendor();el.innerHTML=`<div class="heading"><div><div class="eyebrow">Langkah 3 dari 5</div><h1>Verifikasi Dokumen</h1><p>Unit Keselamatan menilai dokumen dan memberi catatan per pertanyaan.</p></div></div>${picker()}${!v?'<div class="panel empty">Pilih vendor untuk mulai verifikasi.</div>':`<div class="panel"><div class="row between"><div><h2>${esc(v.name)}</h2><p class="muted small">${esc(v.id)} · ${esc(v.scope)}</p></div>${statusTag(v.status)}</div><div class="formgrid">${field('Tanggal verifikasi dokumen','docDate',v.docDate,false,'date')}${field('Nama evaluator','evaluator',v.evaluator||'')}</div><div class="role-note">Setiap akun verifikator menyimpan rekam penilaiannya sendiri. Lebih dari satu verifikator dapat menilai pengajuan yang sama.</div><div class="panel" style="margin-top:14px"><h2>Rekap penilaian seluruh verifikator</h2><p class="muted small">Data dapat dilihat bersama. Nilai per kriteria dan total dihitung dari rata-rata skor verifikator yang telah menyimpan penilaian.</p>${reviewerSummary(v,'reviewByUser')}</div><div class="note small">Skala matriks sesuai formulir: 0; 0,25; 0,5; 0,75; 1. Nilai dicapai = matriks × nilai maksimum. Nilai total dokumen bersifat sementara; nilai akhir mengikuti hasil validasi lapangan.</div>${groups.map(g=>`<div style="margin-top:20px"><h2>${esc(g[0])}</h2><div class="tablewrap"><table><thead><tr><th>Pertanyaan</th><th>Bobot</th><th>Jawaban vendor</th><th>Matriks dokumen</th><th>Nilai</th><th>Keterangan verifikasi</th></tr></thead><tbody>${questions.filter(q=>q.group===g[0]).map(q=>`<tr><td>${esc(q.id)}. ${esc(q.text)}</td><td>${q.max}</td><td>${statusTag(v.answers[q.id]?.answer||'Belum diisi')}<br><small>${(v.answers[q.id]?.files?.length||v.answers[q.id]?.fileId)?(v.answers[q.id]?.files?.length?v.answers[q.id].files.map((f,i)=>`<a href="#" onclick="event.preventDefault();downloadEvidence('${v.id}','${q.id}','${f.id}')">Unduh ${i+1}: ${esc(f.name)}</a>`).join('<br>'):`<a href="#" onclick="event.preventDefault();downloadEvidence('${v.id}','${q.id}')">Unduh: ${esc(v.answers[q.id].fileName||'File bukti')}</a>`):'Tanpa bukti'}</small></td><td><select data-review="${q.id}">${[0,.25,.5,.75,1].map(n=>`<option value="${n}" ${Number(v.reviewByUser?.[session?.username]?.scores?.[q.id]?.score ?? v.review[q.id]?.score ?? 0)===n?'selected':''}>${n.toLocaleString('id-ID')}</option>`).join('')}</select></td><td><b id="val_${q.id}">${(averageMatrix(v,'review',q.id)*q.max).toFixed(2)}</b></td><td><input data-comment="${q.id}" value="${esc(v.reviewByUser?.[session?.username]?.scores?.[q.id]?.comment ?? v.review[q.id]?.comment ?? '')}" placeholder="Catatan pemeriksa"></td></tr>`).join('')}</tbody></table></div></div>`).join('')}<div class="panel" style="margin-top:18px"><div class="row between"><div><div class="muted">Nilai dokumen sementara</div><div class="risk" id="docTotal">${score(v,'review').toFixed(2)} / 565</div></div><div id="docRisk">${badgeRisk(score(v,'review')/565*100)}</div></div><div class="row" style="margin-top:16px"><button onclick="saveReview()">Simpan Verifikasi</button><button class="orange" onclick="submitReview()">Kirim ke Validasi Lapangan →</button><button class="secondary" onclick="returnCorrection()">Minta Perbaikan</button></div></div>`}`;if(v){document.querySelectorAll('[data-review]').forEach(s=>s.onchange=()=>{let q=questions.find(q=>q.id===s.dataset.review);document.getElementById('val_'+q.id).textContent=(Number(s.value)*q.max).toFixed(2);let total=[...document.querySelectorAll('[data-review]')].reduce((a,x)=>a+Number(x.value)*questions.find(q=>q.id===x.dataset.review).max,0);document.getElementById('docTotal').textContent=total.toFixed(2)+' / 565';document.getElementById('docRisk').innerHTML=badgeRisk(total/565*100)});}}
function validationPage(el){let v=vendor();el.innerHTML=`<div class="heading"><div><div class="eyebrow">Langkah 4 dari 5</div><h1>Validasi Dokumen & Lapangan</h1><p>Validasi dilakukan Unit Keselamatan atau Ahli Keselamatan Daerah sesuai penetapan Unit Keselamatan.</p></div></div>${picker()}${!v?'<div class="panel empty">Pilih vendor untuk validasi.</div>':`<div class="panel"><div class="row between"><div><h2>${esc(v.name)}</h2><p class="muted small">${esc(v.scope)}</p></div>${statusTag(v.status)}</div><div class="formgrid">${field('Tanggal validasi lapangan','fieldDate',v.fieldDate,false,'date')}${field('Validator / Ahli Keselamatan Daerah','validator',v.validator||'')}${field('Lokasi validasi','fieldLocation',v.fieldLocation||'')}${field('Hasil tinjauan','fieldResult',v.fieldResult||'Belum dilakukan',false,'select',['Belum dilakukan','Sesuai','Sesuai dengan catatan','Tidak sesuai'])}</div><div class="role-note">Setiap akun validator dapat menyimpan rekam validasinya sendiri. Lebih dari satu validator dapat memvalidasi pengajuan yang sama.</div><div class="panel" style="margin-top:14px"><h2>Hasil verifikasi dokumen</h2><p class="muted small">Ringkasan seluruh verifikator. Nilai dokumen per kriteria adalah rata-rata skor yang sudah disimpan; catatan tiap verifikator ditampilkan agar dapat ditinjau validator.</p>${reviewerSummary(v,'reviewByUser')}</div><div class="panel" style="margin-top:14px"><h2>Rekap penilaian seluruh validator</h2><p class="muted small">Nilai akhir per kriteria dihitung dari rata-rata skor semua validator yang sudah menyimpan penilaian.</p>${reviewerSummary(v,'validationByUser')}</div><div class="note small">Masukkan nilai matriks berdasarkan bukti yang telah dikonfirmasi saat validasi lapangan. Nilai lapangan adalah nilai akhir penetapan kategori RCHSEMS.</div>${groups.map(g=>`<div style="margin-top:20px"><h2>${esc(g[0])}</h2><div class="tablewrap"><table><thead><tr><th>Pertanyaan</th><th>Bobot</th><th>Rata-rata verifikasi dokumen</th><th>Detail skor verifikator</th><th>Matriks lapangan</th><th>Nilai lapangan</th><th>Catatan lapangan</th></tr></thead><tbody>${questions.filter(q=>q.group===g[0]).map(q=>`<tr><td>${esc(q.id)}. ${esc(q.text)}</td><td>${q.max}</td><td><b>${(averageMatrix(v,'review',q.id)*q.max).toFixed(2)}</b><br><small>${averageMatrix(v,'review',q.id).toFixed(2)} / 1</small></td><td><small>${reviewerCriterionDetails(v,q.id,'reviewByUser')}</small></td><td><select data-fieldscore="${q.id}">${[0,.25,.5,.75,1].map(n=>`<option value="${n}" ${Number(v.validationByUser?.[session?.username]?.scores?.[q.id]?.score ?? averageMatrix(v,'validation',q.id) ?? averageMatrix(v,'review',q.id))===n?'selected':''}>${n.toLocaleString('id-ID')}</option>`).join('')}</select></td><td><b id="fv_${q.id}">${(Number(v.validationByUser?.[session?.username]?.scores?.[q.id]?.score ?? v.validation[q.id]?.score ?? v.review[q.id]?.score ?? 0)*q.max).toFixed(2)}</b></td><td><input data-fieldcomment="${q.id}" value="${esc(v.validationByUser?.[session?.username]?.scores?.[q.id]?.comment ?? v.validation[q.id]?.comment ?? '')}" placeholder="Catatan validasi"></td></tr>`).join('')}</tbody></table></div></div>`).join('')}<div class="panel" style="margin-top:18px"><div class="row between"><div><div class="muted">Rata-rata nilai lapangan</div><div class="risk" id="fieldTotal">${score(v,'validation').toFixed(2)} / 565</div></div><div id="fieldRisk">${badgeRisk(score(v,'validation')/565*100)}</div></div><div class="row" style="margin-top:16px"><button onclick="saveValidation()">Simpan Validasi</button><button class="orange" onclick="finalizeValidation()">Tetapkan Hasil →</button></div></div>`}`;if(v){document.querySelectorAll('[data-fieldscore]').forEach(s=>s.onchange=()=>{let q=questions.find(q=>q.id===s.dataset.fieldscore);document.getElementById('fv_'+q.id).textContent=(Number(s.value)*q.max).toFixed(2);let total=[...document.querySelectorAll('[data-fieldscore]')].reduce((a,x)=>a+Number(x.value)*questions.find(q=>q.id===x.dataset.fieldscore).max,0);document.getElementById('fieldTotal').textContent=total.toFixed(2)+' / 565';document.getElementById('fieldRisk').innerHTML=badgeRisk(total/565*100)});}}

function accountsPage(el){
 if(!rolesOf(session?.role).includes('admin')){el.innerHTML='<div class="panel empty">Menu ini hanya untuk Admin.</div>';return}
 const internal=accounts.filter(a=>rolesOf(a.role).some(r=>['verifikator','validator','pengadaan','admin'].includes(r)));
 el.innerHTML=`<div class="heading"><div><div class="eyebrow">Administrasi sistem</div><h1>Kelola Akun Internal</h1><p>Admin dapat mendaftarkan akun Verifikator, Validator, dan Bagian Pengadaan. Satu akun dapat memiliki lebih dari satu peran internal.</p></div></div>
 <div class="panel"><h2>Daftarkan akun internal</h2><form id="internalAccountForm"><div class="formgrid">
 <div class="field"><label>Nama lengkap *</label><input name="name" required placeholder="Nama petugas"></div>
 <div class="field"><label>Email / username *</label><input name="username" type="email" required placeholder="nama@kai.co.id"></div>
 <div class="field"><label>Password sementara * (min. 12 karakter)</label><input name="password" type="password" required minlength="12" placeholder="Password awal"></div>
 <div class="field"><label>Peran internal *</label><div class="role-options"><label class="role-option"><input type="checkbox" name="internalRole" value="verifikator"> <span>Verifikator</span></label><label class="role-option"><input type="checkbox" name="internalRole" value="validator"> <span>Validator</span></label><label class="role-option"><input type="checkbox" name="internalRole" value="pengadaan"> <span>Bagian Pengadaan</span></label><label class="role-option"><input type="checkbox" name="internalRole" value="admin"> <span>Admin</span></label></div><small class="muted">Jangan pilih Vendor untuk akun internal. Verifikator dan Validator boleh dipilih bersamaan.</small></div>
 </div><div class="row between" style="margin-top:16px"><span class="muted small">Akun tersimpan di server dengan password terenkripsi satu arah.</span><button type="submit">＋ Buat Akun Internal</button></div><div id="internalAccountMsg" class="small" style="margin-top:10px"></div></form></div>
 <div class="panel" style="margin-top:16px"><div class="row between"><h2>Daftar akun internal</h2><span class="tag">${internal.length} akun</span></div>${internal.length?`<div class="tablewrap"><table><thead><tr><th>Nama</th><th>Email / username</th><th>Peran</th><th>Aksi</th></tr></thead><tbody>${internal.map(a=>`<tr><td>${esc(a.name||'')}</td><td>${esc(a.username)}</td><td>${esc(roleLabel(a.role))}</td><td><button class="secondary" type="button" onclick="resetInternalPassword('${encodeURIComponent(a.username).replaceAll("'","%27")}')">Atur ulang password</button> ${!rolesOf(a.role).includes('admin')&&a.username!==session.username?`<button class="secondary" type="button" onclick="deleteInternalAccount('${encodeURIComponent(a.username).replaceAll("'","%27")}')">Hapus</button>`:''}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Belum ada akun internal tambahan.</div>'}</div>
 <div class="note small">Akses diperiksa oleh server. Penghapusan menonaktifkan akun dan mempertahankan riwayat penilaian.</div>`;
 document.getElementById('internalAccountForm').onsubmit=createAccount;
}


function riskPage(el){let vs=db.vendors;el.innerHTML=`<div class="heading"><div><div class="eyebrow">Langkah 5 dari 5</div><h1>Hasil & Lingkup Risiko</h1><p>Nilai akhir memakai hasil validasi lapangan. Lingkup sertifikat dibatasi pada perusahaan/cabang dan lingkup pekerjaan yang divalidasi.</p></div><button class="secondary" onclick="exportData()">Ekspor JSON</button></div><div class="panel"><h2>Aturan kategori sesuai formulir verifikasi</h2><div class="cards" style="grid-template-columns:repeat(4,minmax(0,1fr))"><div><span class="tag orange">Risiko Tinggi</span><div class="metric">≥ 70</div><small class="muted">Nilai PK</small></div><div><span class="tag green">Risiko Menengah</span><div class="metric">50–&lt;70</div><small class="muted">Nilai PK</small></div><div><span class="tag green">Risiko Rendah</span><div class="metric">35–&lt;50</div><small class="muted">Nilai PK</small></div><div><span class="tag red">Tidak Lulus</span><div class="metric">&lt; 35</div><small class="muted">Tidak memenuhi ambang</small></div></div><p class="muted small">Nilai persentase = jumlah (matriks lapangan × nilai maksimum) ÷ 565 × 100. Ambang di atas berasal dari Form Verifikasi yang diunggah; konfigurasi final perlu disahkan pemilik prosedur.</p></div><div class="panel" style="margin-top:16px"><h2>Rekap hasil penilaian</h2>${vs.length?vendorTable(vs):'<div class="empty">Belum ada hasil penilaian.</div>'}</div><div class="panel" style="margin-top:16px"><h2>Sertifikat rekanan — pratinjau</h2><div class="field" style="max-width:550px"><label>Pilih vendor tervalidasi</label><select id="certVendor"><option value="">Pilih vendor...</option>${vs.filter(v=>v.status==='Tervalidasi').map(v=>`<option value="${v.id}">${esc(v.name)} — ${esc(v.id)}</option>`).join('')}</select></div><button style="margin-top:12px" onclick="previewCert()">Buat Pratinjau Sertifikat</button><div id="certPreview"></div><p class="muted small">Penerbitan resmi sertifikat tetap dilakukan Vendor Management sesuai kewenangan dan persetujuan internal.</p></div>`}
function previewCert(){
 let v=db.vendors.find(x=>x.id===document.getElementById('certVendor').value),out=document.getElementById('certPreview');
 if(!v){out.innerHTML='<p class="muted">Pilih vendor terlebih dahulu.</p>';return}
 let n=score(v,'validation')/565*100, r=risk(n), status=(n<35?'TIDAK LULUS':(n>=70?'RISIKO TINGGI':(n>=50?'RISIKO MENENGAH':'RISIKO RENDAH'))), validDate=v.fieldDate||'-';
 let logo=`<img class="cert-logo" src="data:image/png;base64," alt="Logo KAI">`;
 out.innerHTML=`<div class="certificate" id="certificateOnly"><div class="cert-topline"></div>${logo}<p class="cert-org">PT Kereta Api Indonesia (Persero)</p><h1 class="cert-title">SERTIFIKAT HASIL PENILAIAN</h1><p class="cert-subtitle">Railway Contractor HSE Management System</p><div class="cert-rule"></div><p class="cert-award">Dengan ini menyatakan bahwa rekanan berikut telah mengikuti proses penilaian RCHSEMS</p><h2 class="cert-vendor">${esc(v.name)}</h2><p class="cert-scope">Lingkup pekerjaan: <strong>${esc(v.scope)}</strong></p><div class="cert-score">${n.toFixed(2)} <span style="font-size:14px;font-weight:600">/ 100</span></div><span class="cert-status" style="background:${n<35?'#ffebe9':n>=70?'#fff1df':'#e4f7ee'};color:${n<35?'#b42318':n>=70?'#a65300':'#08764c'}">${status}</span><div class="cert-meta"><span>Nomor registrasi: <b>${esc(v.id)}</b></span><span>Tanggal validasi: <b>${esc(validDate)}</b></span><span>Status: <b>${esc(v.status||'Tervalidasi')}</b></span></div><p class="cert-validity">Masa berlaku indikatif 2 (dua) tahun sejak tanggal validasi lapangan, sesuai prosedur RCHSEMS dan ketentuan penerbitan sertifikat yang berlaku.</p><div class="cert-signatures"><div class="cert-sign"><strong>Unit Keselamatan</strong><span>Validasi penilaian</span></div><div class="cert-sign"><strong>Vendor Management</strong><span>Penerbitan sesuai kewenangan</span></div></div></div><div class="cert-actions"><button onclick="window.print()">Cetak / Simpan PDF</button><span class="muted small" style="align-self:center">Saat mencetak, hanya sertifikat yang akan dicetak.</span></div>`
}

// Server-backed persistence. No credentials or business data are stored in localStorage.
let busy=false, uploads=0;
async function api(path, method='GET', data=null){
 const headers={'Accept':'application/json','X-CSRF-TOKEN':document.querySelector('meta[name="csrf-token"]').content};
 if(data && !(data instanceof FormData))headers['Content-Type']='application/json';
 const res=await fetch('/api'+path,{method,headers,credentials:'same-origin',body:data?(data instanceof FormData?data:JSON.stringify(data)):undefined});
 const csrf=res.headers.get('X-CSRF-TOKEN');if(csrf)document.querySelector('meta[name="csrf-token"]').content=csrf;
 let result;try{result=await res.json()}catch{result={message:'Respons server tidak valid.'}}
 if(!res.ok){if(res.status===401){session=null;loginReady()}if(res.status===419)result.message='Sesi kedaluwarsa. Muat ulang halaman dan login kembali.';throw new Error(Object.values(result.errors||{}).flat().join('\n')||result.message||'Permintaan gagal.');}
 return result;
}
async function action(fn){if(busy)return;busy=true;try{await fn()}catch(e){alert(e.message)}finally{busy=false}}
async function refresh(){const state=await api('/state');session=state.session;db={vendors:state.vendors};accounts=state.accounts;}
function replaceVendor(v){const i=db.vendors.findIndex(x=>x.id===v.id);if(i<0)db.vendors.push(v);else db.vendors[i]=v;currentId=v.id;}
async function logout(){await action(async()=>{await api('/logout','POST');location.reload()})}
async function changePassword(){const old=prompt('Password saat ini:');if(old===null)return;const pw=prompt('Password baru (minimal 12 karakter):');if(pw===null)return;await action(async()=>{await api('/password','PUT',{current_password:old,password:pw});alert('Password berhasil diubah.');})}
document.getElementById('authForm').addEventListener('submit',async e=>{
 e.preventDefault();const button=document.getElementById('authSubmit');button.disabled=true;
 try{await api(authMode==='register'?'/register':'/login','POST',{username:document.getElementById('authUser').value.trim().toLowerCase(),password:document.getElementById('authPass').value,name:document.getElementById('authName').value.trim()});await refresh();document.getElementById('authPass').value='';page=defaultPage();loginReady();render();}
 catch(err){document.getElementById('authError').textContent=err.message}finally{button.disabled=false}
});
async function saveProfile(e){e.preventDefault();const data=Object.fromEntries(new FormData(e.target));await action(async()=>{const v=await api(currentId?'/vendors/'+currentId:'/vendors',currentId?'PUT':'POST',data);replaceVendor(v);go('questionnaire')});}
async function submitQuestionnaire(e){
 e.preventDefault();if(uploads){alert('Tunggu sampai seluruh unggahan selesai.');return;}
 const answers=questions.map(q=>({question_id:q.id,answer:e.target.querySelector(`[name="a_${q.id}"]:checked`)?.value||'',note:e.target.elements[`note_${q.id}`].value}));
 if(answers.some(a=>!a.answer)){alert('Lengkapi jawaban untuk seluruh 49 pertanyaan.');return;}
 await action(async()=>{replaceVendor(await api('/vendors/'+currentId+'/answers','POST',{answers}));go(canAccess('verification')?'verification':'vendors');alert('Pra-kualifikasi tersimpan dan masuk antrean verifikasi.');});
}
async function uploadEvidence(inp){
 const v=vendor(),qid=inp.dataset.doc,files=[...inp.files];if(!v||!files.length)return;uploads++;inp.disabled=true;
 try{for(const file of files){if(file.size>15*1024*1024)throw new Error(file.name+': maksimal 15 MB.');const fd=new FormData();fd.append('question_id',qid);fd.append('file',file);const stored=await api('/vendors/'+v.id+'/evidence','POST',fd);v.answers[qid]??={answer:'',note:'',files:[]};v.answers[qid].files??=[];v.answers[qid].files.push(stored);inp.nextElementSibling.textContent=v.answers[qid].files.map(x=>x.name).join('; ')+' — tersimpan di server';}}
 catch(e){alert(e.message)}finally{uploads--;inp.disabled=false;inp.value='';}
}
function downloadEvidence(vendorId,qid,fileId){if(fileId)window.open('/api/evidence/'+encodeURIComponent(fileId),'_blank','noopener');}
function assessmentPayload(stage,act){const review=stage==='review',attr=review?'data-review':'data-fieldscore',comment=review?'data-comment':'data-fieldcomment';const data={action:act,scores:[...document.querySelectorAll('['+attr+']')].map(el=>({question_id:el.getAttribute(attr),score:Number(el.value),comment:document.querySelector(`[${comment}="${el.getAttribute(attr)}"]`).value}))};for(const f of (review?['docDate','evaluator']:['fieldDate','validator','fieldLocation','fieldResult']))data[f]=document.querySelector(`[name="${f}"]`)?.value||null;return data;}
async function saveAssessment(stage,act){await action(async()=>{const v=await api('/vendors/'+currentId+'/assessments/'+stage,'POST',assessmentPayload(stage,act));replaceVendor(v);if(act==='advance')go(canAccess('validation')?'validation':'vendors');else if(act==='finalize')go('risk');else render();alert('Data berhasil disimpan di server.');});}
function saveReview(){return saveAssessment('review','save')}
function submitReview(){return saveAssessment('review','advance')}
function returnCorrection(){return saveAssessment('review','return')}
function saveValidation(){return saveAssessment('validation','save')}
function finalizeValidation(){if(confirm('Tetapkan hasil akhir? Penilaian akan dikunci. Pastikan semua validator telah menyimpan nilainya.'))return saveAssessment('validation','finalize')}
async function createAccount(e){e.preventDefault();const fd=new FormData(e.target);await action(async()=>{await api('/accounts','POST',{username:String(fd.get('username')).trim().toLowerCase(),name:fd.get('name'),password:fd.get('password'),role:fd.getAll('internalRole')});await refresh();render();alert('Akun internal berhasil dibuat.');})}
async function resetInternalPassword(encoded){const email=decodeURIComponent(encoded),a=accounts.find(x=>x.username===email);if(!a)return;const password=prompt('Password baru (minimal 12 karakter) untuk '+email);if(password===null)return;await action(async()=>{await api('/accounts/'+a.id+'/password','PUT',{password});alert('Password diubah dan sesi akun tersebut dihentikan.');if(email===session.username)location.reload();})}
async function deleteInternalAccount(encoded){const email=decodeURIComponent(encoded),a=accounts.find(x=>x.username===email);if(!a||!confirm('Nonaktifkan akun '+email+'? Riwayat penilaian tetap disimpan.'))return;await action(async()=>{await api('/accounts/'+a.id,'DELETE');await refresh();render();})}
function exportData(){window.location.href='/api/export';}
// Refresh persisted state when navigating. Renderers remain identical to the mockup.
const originalGo=go;
go=function(p){if(busy)return originalGo(p);action(async()=>{await refresh();originalGo(p)});};
const originalRender=render;
render=function(){
 originalRender();
 document.querySelectorAll('[onclick*="go(\'register\')"]').forEach(b=>{if(!canAccess('register'))b.remove()});
 const v=vendor();
 if(v&&page==='questionnaire'&&!['Menunggu Pengisian','Perlu Perbaikan'].includes(v.status)){
  document.querySelectorAll('#qForm input,#qForm button').forEach(el=>el.disabled=true);
  const note=document.createElement('div');note.className='note';note.textContent='Pengajuan sedang diproses atau telah final. Formulir terkunci sampai dikembalikan untuk perbaikan.';document.getElementById('qForm').prepend(note);
 }
 if(v&&page==='questionnaire'&&v.status==='Perlu Perbaikan'){
  const box=document.createElement('div');box.className='panel';box.innerHTML='<h2>Catatan perbaikan verifikator</h2>'+questions.map(q=>`<p><b>${esc(q.id)}</b> ${reviewerCriterionDetails(v,q.id,'reviewByUser')}</p>`).join('');document.getElementById('qForm').prepend(box);
 }
 if(v&&((page==='verification'&&v.status!=='Menunggu Verifikasi Dokumen')||(page==='validation'&&v.status!=='Menunggu Validasi Lapangan'))){
  document.querySelectorAll('#view [data-review],#view [data-comment],#view [data-fieldscore],#view [data-fieldcomment],#view input[name],#view select[name],#view button').forEach(el=>el.disabled=true);
 }
};
(async()=>{try{await refresh();page=defaultPage();loginReady();render()}catch(e){loginReady();if(!/Unauthenticated/.test(e.message))document.getElementById('authError').textContent=e.message}})();
// Mask password entry rather than using a plain browser prompt.
function passwordDialog(title,withCurrent=false){return new Promise(resolve=>{const d=document.createElement('dialog');d.style.cssText='border:1px solid #e0e7f0;border-radius:15px;padding:24px;max-width:440px;width:90%';d.innerHTML=`<form><h2>${esc(title)}</h2>${withCurrent?'<div class="field"><label>Password saat ini</label><input name="current" type="password" autocomplete="current-password" required></div>':''}<div class="field"><label>Password baru (minimal 12 karakter)</label><input name="password" type="password" autocomplete="new-password" minlength="12" maxlength="128" required></div><div class="row" style="margin-top:16px"><button type="submit">Simpan</button><button class="secondary" type="button" data-cancel>Batal</button></div></form>`;document.body.appendChild(d);function finish(v){d.close();d.remove();resolve(v)}d.querySelector('form').onsubmit=e=>{e.preventDefault();finish({password:d.querySelector('[name=password]').value,current_password:d.querySelector('[name=current]')?.value})};d.querySelector('[data-cancel]').onclick=()=>finish(null);d.oncancel=e=>{e.preventDefault();finish(null)};d.showModal();})}
changePassword=async function(){const data=await passwordDialog('Ganti password',true);if(!data)return;await action(async()=>{await api('/password','PUT',data);alert('Password berhasil diubah.');})};
resetInternalPassword=async function(encoded){const email=decodeURIComponent(encoded),a=accounts.find(x=>x.username===email);if(!a)return;const data=await passwordDialog('Atur ulang password: '+email);if(!data)return;await action(async()=>{await api('/accounts/'+a.id+'/password','PUT',data);alert('Password diubah dan sesi akun tersebut dihentikan.');if(email===session.username)location.reload();})};
